WFJ.Data.add("book", {
  ["0b3a2f215f72867b"] = { "Gli agenti hanno avviato il rastrellamento, riscontrando una presenza significativa di worg. Si raccomanda l'invio di squadre di caccia per ridurre questa minaccia.\n\nAlcuni gnoll non morti sono stati trovati nel podere chiamato ⟦The Dead Field=Agro dei Morti⟧. Il loro scopo al podere non è noto, anche se i loro movimenti e il loro grado di prontezza fanno pensare a un'azione militare imminente. Nel tempo in cui sono stati osservati, tra gli gnoll non sono stati individuati capi di rilievo. Si presume che attendano l'arrivo di comandanti o di rinforzi.", "." },
  ["0b3c2e1e69cdb401"] = { "Heliana,\n\nio, Vargus, sono ancora vivo, nonostante i tuoi desideri contrari. Detesto andarmene in giro per la campagna con questa armatura ridicola.\n\nGli ultimi ordini ci mandano verso Andorhal a cercare grano o qualche altra sciocchezza del genere. Perché mai dovrebbero importarmi le scorte di cibo di Andorhal, fra tutti i posti? L'idea stessa di stare nell'esercito è assurda.\n\nStai pur certa, zia Heliana, che tornerò per la tua eredità; anche se fossi gravemente ferito e rimanessi senza cibo, il puro rancore mi spingerebbe sempre avanti.\n\nVargus", "." },
  ["0b5a99a6a5db0366"] = { "<HTML>\n<BODY>\n<H1 align=\"center\">GRADI DEGLI UFFICIALI DELL'ORDA</H1><BR/>\n<P align=\"center\">Parte 1</P>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank14\" align=\"left\"/><BR/>\n<P align=\"right\">Gran Signore della Guerra</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank13\" align=\"left\"/><BR/>\n<P align=\"right\">Signore della Guerra</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank12\" align=\"left\"/><BR/>\n<P align=\"right\">Generale</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank11\" align=\"left\"/><BR/>\n<P align=\"right\">Tenente Generale</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank10\" align=\"left\"/><BR/>\n<P align=\"right\">Campione</P><BR/><BR/>\n</BODY>\n</HTML>", "." },
  ["0b6e7fc958584277"] = { "Giorno 3\n\nQuel ringhio è andato avanti tutta la notte e mi ha seguito per tutto il giorno, distraendomi dalla caccia al minerale. Credo che un orso mi stia seguendo!\n\nSpero che si avvicini. Gli pianterò il piccone in testa!", "." },
  ["0bd31da37a88f42d"] = { "Questa incudine è di proprietà di Jordan Stilwell. Si prega di NON usarla!\n\n- Jordan", "." },
